@pytest.mark.parametrize("norm_type", [mpl.colors.Normalize, mpl.colors.LogNorm])
@pytest.mark.parametrize("limit_kws", [{}, {"vmin": 0, "vmax": 1}])
def test_explicit_norm_vlims(self, norm_type, limit_kws):

    data = np.array([[.2, .4], [.6, .8]])
    norm = norm_type(vmin=.1, vmax=.9)
    ax = mat.heatmap(data, norm=norm, **limit_kws)
    mesh = ax.collections[0]
    assert mesh.norm is norm
    assert mesh.get_clim() == (.1, .9)

